    def clean(n):
        if isinstance(n,dict):return {k:clean(v) for k,v in n.items()}
        if isinstance(n,list):return [clean(v) for v in n]
        if isinstance(n,str):
            for a,b in replacements.items():n=n.replace(a,b)
        return n
